   147	/**
   148	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
   149	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
   150	 * (half-even) at every step.
   151	 */
   152	public final class PriceCalculator {
   153	
   154	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
   155	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
   156	
   157	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
   158	        int nights = 0;
   159	        BigDecimal subtotal = cents(BigDecimal.ZERO);
   160	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
   161	            subtotal = subtotal.add(nightPrice(room, night));
   162	            nights++;
   163	        }
   164	        BigDecimal discount = switch (ratePlan) {
   165	            case STANDARD -> cents(BigDecimal.ZERO);
   166	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
   167	        };
   168	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
   169	    }
   170	
   171	    BigDecimal nightPrice(Room room, LocalDate night) {
   172	        BigDecimal nightlyRate = room.nightlyRate();
   173	        if (isHighSeason(night)) {
   174	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
   175	        }
   176	        return cents(nightlyRate);
   177	    }
   178	
   179	    /** High season: from December 15 to the end of February, and the whole of July. */
   180	    static boolean isHighSeason(LocalDate date) {
   181	        Month month = date.getMonth();
   182	        return month == Month.JANUARY
   183	                || month == Month.FEBRUARY
   184	                || month == Month.JULY
   185	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
   186	    }
   187	
   188	    static BigDecimal cents(BigDecimal value) {
   189	        return value.setScale(2, RoundingMode.HALF_EVEN);
   190	    }
